import{_ as t}from"./chunks/100.Bym1HttY.js";import{_ as o,o as a,c as n,ak as r}from"./chunks/framework.Ba6sv-31.js";const s="/projects/AiBlockSensor/en/latest/assets/1.CQ4TMJZL.webp",i="/projects/AiBlockSensor/en/latest/assets/2.CkbfNN24.webp",l="/projects/AiBlockSensor/en/latest/assets/3.an9mZ4CH.webp",c="/projects/AiBlockSensor/en/latest/assets/4.fG7yK1nX.webp",d="/projects/AiBlockSensor/en/latest/assets/5.Dkf_Uy4Y.webp",x=JSON.parse('{"title":"5. Sound Sensor","description":"","frontmatter":{},"headers":[],"relativePath":"docs/5. Sound Sensor.md","filePath":"docs/5. Sound Sensor.md"}'),h={name:"docs/5. Sound Sensor.md"};function p(m,e,u,g,_,f){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="_5-sound-sensor" tabindex="-1">5. Sound Sensor <a class="header-anchor" href="#_5-sound-sensor" aria-label="Permalink to &quot;5. Sound Sensor&quot;">​</a></h1><h2 id="_5-1-introduction" tabindex="-1">5.1 Introduction <a class="header-anchor" href="#_5-1-introduction" aria-label="Permalink to &quot;5.1 Introduction&quot;">​</a></h2><p>This section introduces the sound sensor, designed to measure ambient sound volume. The module serves diverse applications, primarily in sound-activated robots, sound-triggered switches, and noise alarm systems.</p><img loading="lazy" height="348" width="517" src="'+s+'" class="common_img" style="width:300px;"><h2 id="_5-2-technical-specifications" tabindex="-1">5.2 Technical Specifications <a class="header-anchor" href="#_5-2-technical-specifications" aria-label="Permalink to &quot;5.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Microphone type</td><td style="text-align:center;">Electret condenser</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">39.5 × 23.4 × 18.7 mm</td></tr></tbody></table><h2 id="_5-3-hands-on-project" tabindex="-1">5.3 Hands-On Project <a class="header-anchor" href="#_5-3-hands-on-project" aria-label="Permalink to &quot;5.3 Hands-On Project&quot;">​</a></h2><h3 id="_5-3-1-project-introduction" tabindex="-1">5.3.1 Project Introduction <a class="header-anchor" href="#_5-3-1-project-introduction" aria-label="Permalink to &quot;5.3.1 Project Introduction&quot;">​</a></h3><p>This project uses the sound sensor to read ambient sound analog values and print the readings to the serial port. Clapping or speaking changes the ambient sound volume, allowing you to check data changes in the serial monitor to clarify the volume detection logic of the sound sensor.</p><h3 id="_5-3-2-hardware-wiring" tabindex="-1">5.3.2 Hardware Wiring <a class="header-anchor" href="#_5-3-2-hardware-wiring" aria-label="Permalink to &quot;5.3.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the sound sensor to port <strong>A</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="390" width="1039" src="'+i+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This sensor supports connection to any port among A, B, C, or D on the controller. Ensure that the port selected in the program matches the physical wiring.</strong></p></div><h3 id="_5-3-3-adding-extensions" tabindex="-1">5.3.3 Adding Extensions <a class="header-anchor" href="#_5-3-3-adding-extensions" aria-label="Permalink to &quot;5.3.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Sound sensor</strong> under the <strong>Input Module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+l+'" class="common_img" style="width:800px;"><h3 id="_5-3-4-complete-program-and-analysis" tabindex="-1">5.3.4 Complete Program and Analysis <a class="header-anchor" href="#_5-3-4-complete-program-and-analysis" aria-label="Permalink to &quot;5.3.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>Inside the main program loop, the sound volume analog value from the sound sensor on port A is continuously sampled.</p></li><li><p>The acquired volume analog value is printed over the serial port.</p></li><li><p>A 0.1-second wait is configured for rapid data refresh, capturing dynamic fluctuations in sound level.</p></li></ol><img loading="lazy" height="258" width="678" src="'+c+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1fLfLXEVjSMZdojOq7C44xJqZIBm4MDem?usp=sharing" target="_blank" rel="noreferrer">Program Files/ 05 Sound Sensor.sb3</a>.</strong></p></div><h3 id="_5-3-5-program-upload" tabindex="-1">5.3.5 Program Upload <a class="header-anchor" href="#_5-3-5-program-upload" aria-label="Permalink to &quot;5.3.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+t+'" class="common_img" style="width:800px;"><h3 id="_5-3-6-program-outcome" tabindex="-1">5.3.6 Program Outcome <a class="header-anchor" href="#_5-3-6-program-outcome" aria-label="Permalink to &quot;5.3.6 Program Outcome&quot;">​</a></h3><p>Once the program upload is complete, check the serial monitor in the lower-right corner of the programming software. In quiet environments, the serial output values remain low. Clapping hands or speaking loudly increases the detected volume, causing the printed values to rise accordingly. The readings range from 0 to 100.</p><img loading="lazy" height="955" width="1340" src="'+d+'" class="common_img" style="width:800px;">',26)])])}const k=o(h,[["render",p]]);export{x as __pageData,k as default};
